        else if (fub_axi_araddr >= 32'h00026000 && fub_axi_araddr <= 32'h00026FFF) begin
            comb_slave_select_ar[15] = 1'b1;  // slv6
        end
        else if (fub_axi_araddr >= 32'h00027000 && fub_axi_araddr <= 32'h00027FFF) begin
            comb_slave_select_ar[16] = 1'b1;  // slv7
        end
        else if (fub_axi_araddr >= 32'h00100000 && fub_axi_araddr <= 32'h0010FFFF) begin
            comb_slave_select_ar[17] = 1'b1;  // ext0
        end
        else if (fub_axi_araddr >= 32'h00110000 && fub_axi_araddr <= 32'h0011FFFF) begin
            comb_slave_select_ar[18] = 1'b1;  // ext1
        end
        else if (fub_axi_araddr >= 32'h00120000 && fub_axi_araddr <= 32'h0012FFFF) begin
            comb_slave_select_ar[19] = 1'b1;  // ext2
        end
        else if (fub_axi_araddr >= 32'h00130000 && fub_axi_araddr <= 32'h0013FFFF) begin
            comb_slave_select_ar[20] = 1'b1;  // ext3
        end
        else begin  // Full address range (catch-all)
            comb_slave_select_ar[21] = 1'b1;  // subtractive
        end
    end

    // Bridge ID for read channel (constant - tied to BRIDGE_ID parameter)
    assign bridge_id_ar = BRIDGE_ID_WIDTH'(BRIDGE_ID);

    // ================================================================
    // Width adaptation - Master: 32b
    // Connected to slaves with widths: [32]
    // ================================================================

    // Per-width path-active gates (see comment in adapter_generator.py).
    logic aw_gate_ok;
    logic ar_gate_ok;
    logic aw_path_active_32b;
    assign aw_path_active_32b = (comb_slave_select_aw[0] | comb_slave_select_aw[1] | comb_slave_select_aw[2] | comb_slave_select_aw[3] | comb_slave_select_aw[4] | comb_slave_select_aw[5] | comb_slave_select_aw[6] | comb_slave_select_aw[7] | comb_slave_select_aw[8] | comb_slave_select_aw[9] | comb_slave_select_aw[10] | comb_slave_select_aw[11] | comb_slave_select_aw[12] | comb_slave_select_aw[13] | comb_slave_select_aw[14] | comb_slave_select_aw[15] | comb_slave_select_aw[16] | comb_slave_select_aw[17] | comb_slave_select_aw[18] | comb_slave_select_aw[19] | comb_slave_select_aw[20] | comb_slave_select_aw[21]) && aw_gate_ok;
    logic w_path_active_32b;
    assign w_path_active_32b = w_slave_select[0] | w_slave_select[1] | w_slave_select[2] | w_slave_select[3] | w_slave_select[4] | w_slave_select[5] | w_slave_select[6] | w_slave_select[7] | w_slave_select[8] | w_slave_select[9] | w_slave_select[10] | w_slave_select[11] | w_slave_select[12] | w_slave_select[13] | w_slave_select[14] | w_slave_select[15] | w_slave_select[16] | w_slave_select[17] | w_slave_select[18] | w_slave_select[19] | w_slave_select[20] | w_slave_select[21];
    logic ar_path_active_32b;
    assign ar_path_active_32b = (comb_slave_select_ar[0] | comb_slave_select_ar[1] | comb_slave_select_ar[2] | comb_slave_select_ar[3] | comb_slave_select_ar[4] | comb_slave_select_ar[5] | comb_slave_select_ar[6] | comb_slave_select_ar[7] | comb_slave_select_ar[8] | comb_slave_select_ar[9] | comb_slave_select_ar[10] | comb_slave_select_ar[11] | comb_slave_select_ar[12] | comb_slave_select_ar[13] | comb_slave_select_ar[14] | comb_slave_select_ar[15] | comb_slave_select_ar[16] | comb_slave_select_ar[17] | comb_slave_select_ar[18] | comb_slave_select_ar[19] | comb_slave_select_ar[20] | comb_slave_select_ar[21]) && ar_gate_ok;
    logic b_path_active_32b;
    assign b_path_active_32b = b_slave_select[0] | b_slave_select[1] | b_slave_select[2] | b_slave_select[3] | b_slave_select[4] | b_slave_select[5] | b_slave_select[6] | b_slave_select[7] | b_slave_select[8] | b_slave_select[9] | b_slave_select[10] | b_slave_select[11] | b_slave_select[12] | b_slave_select[13] | b_slave_select[14] | b_slave_select[15] | b_slave_select[16] | b_slave_select[17] | b_slave_select[18] | b_slave_select[19] | b_slave_select[20] | b_slave_select[21];
    logic r_path_active_32b;
    assign r_path_active_32b = r_slave_select[0] | r_slave_select[1] | r_slave_select[2] | r_slave_select[3] | r_slave_select[4] | r_slave_select[5] | r_slave_select[6] | r_slave_select[7] | r_slave_select[8] | r_slave_select[9] | r_slave_select[10] | r_slave_select[11] | r_slave_select[12] | r_slave_select[13] | r_slave_select[14] | r_slave_select[15] | r_slave_select[16] | r_slave_select[17] | r_slave_select[18] | r_slave_select[19] | r_slave_select[20] | r_slave_select[21];

    // ================================================================
    // Direct passthrough: 32b → 32b (no converter)
    // Requests: fub_axi_* → host_32b_*
    // Responses: host_32b_* → MUX → fub_axi_*
    // ================================================================

    // AW channel (request: fub → output)
    assign host_32b_aw.id     = fub_axi_awid;
    assign host_32b_aw.addr   = fub_axi_awaddr;
    assign host_32b_aw.len    = fub_axi_awlen;
    assign host_32b_aw.size   = fub_axi_awsize;
    assign host_32b_aw.burst  = fub_axi_awburst;
    assign host_32b_aw.lock   = fub_axi_awlock;
    assign host_32b_aw.cache  = fub_axi_awcache;
    assign host_32b_aw.prot   = fub_axi_awprot;
    assign host_32b_aw.qos    = fub_axi_awqos;
    assign host_32b_aw.region = fub_axi_awregion;
    assign host_32b_aw.user   = fub_axi_awuser;
    assign host_32b_awvalid   = fub_axi_awvalid && aw_path_active_32b;
    // awready routed via MUX

    // W channel (request: fub → output)
    assign host_32b_w.data  = fub_axi_wdata;
    assign host_32b_w.strb  = fub_axi_wstrb;
    assign host_32b_w.last  = fub_axi_wlast;
    assign host_32b_w.user  = fub_axi_wuser;
    assign host_32b_wvalid  = fub_axi_wvalid && w_path_active_32b;
    // wready routed via MUX

    // B channel (response: output → MUX → fub)
    // Ready gated by the response head — see b_path_active comment.
    assign host_32b_bready = fub_axi_bready && b_path_active_32b;
    // bid, bresp, bvalid routed via MUX (user field ignored)

    // AR channel (request: fub → output)
    assign host_32b_ar.id     = fub_axi_arid;
    assign host_32b_ar.addr   = fub_axi_araddr;
    assign host_32b_ar.len    = fub_axi_arlen;
    assign host_32b_ar.size   = fub_axi_arsize;
    assign host_32b_ar.burst  = fub_axi_arburst;
    assign host_32b_ar.lock   = fub_axi_arlock;
    assign host_32b_ar.cache  = fub_axi_arcache;
    assign host_32b_ar.prot   = fub_axi_arprot;
    assign host_32b_ar.qos    = fub_axi_arqos;
    assign host_32b_ar.region = fub_axi_arregion;
    assign host_32b_ar.user   = fub_axi_aruser;
    assign host_32b_arvalid   = fub_axi_arvalid && ar_path_active_32b;
    // arready routed via MUX

    // R channel (response: output → MUX → fub)
    // Ready gated by the response head — see r_path_active comment.
    assign host_32b_rready = fub_axi_rready && r_path_active_32b;
    // rid, rdata, rresp, rlast, rvalid routed via MUX (user field ignored)

    // ================================================================
    // Response MUX - Route responses from width-specific paths
    // back to fub_axi_* based on address decode
    //
    // Request side (arready/awready/wready) uses the combinational
    // slave_select_{ar,aw} (valid while {ar,aw}valid is asserted).
    //
    // Response side (rvalid/rdata/..., bvalid/bid/...) cannot reuse
    // the combinational decode because fub_axi_{ar,aw}addr no longer
    // holds the request address once the {AR,AW} handshake completes
    // -- the decode reverts (typically to slave 0) and drops the
    // response. So we track slave_select_{ar,aw} per outstanding
    // request in a small FIFO captured at handshake, popped at
    // R-last / B; the FIFO head drives the response MUX.
    // ================================================================

    // OUTPUT slave_select_aw mirrors the live combinational decode.
    assign slave_select_aw = comb_slave_select_aw;

    localparam int AW_TRK_DEPTH = 16;
    localparam int AW_TRK_AW    = 4;
    // -------- AW per-ID target table (fixes bridge GitHub #119 L1) --------
    // 2 entries indexed by the ID's low 1 bit(s). An ID with requests
    // in flight may only add more to the SAME slave (AXI same-ID order);
    // any other ID may go to any slave. IDs that share the index bits are
    // treated as one ID: safe, at worst a needless stall.
    localparam int AW_IDT_N = 2;
    logic [AW_TRK_AW:0]   aw_idt_cnt [AW_IDT_N];
    logic [NUM_SLAVES-1:0] aw_idt_tgt [AW_IDT_N];
    logic [AW_TRK_AW:0]   aw_out_cnt;
    // Next counts, and registered flags taken from them, so the gate a
    // request sees is a 1-bit lookup and a one-hot AND, not a counter
    // mux and compare in series with the crossbar's arbitration.
    logic [AW_TRK_AW:0]   aw_idt_cnt_nx [AW_IDT_N];
    logic [AW_TRK_AW:0]   aw_out_cnt_nx;
    logic [AW_IDT_N-1:0] aw_idt_busy;
    logic                  aw_trk_full;
    logic [0:0] aw_idt_widx, aw_idt_ridx;
    logic aw_idt_push, aw_idt_pop;
    assign aw_idt_widx = fub_axi_awid[0:0];
    assign aw_idt_ridx = fub_axi_bid[0:0];
    assign aw_idt_push = fub_axi_awvalid && fub_axi_awready;
    assign aw_idt_pop  = fub_axi_bvalid && fub_axi_bready;
    logic [1:0] aw_inc_n;   // pushes this cycle
    assign aw_inc_n = 2'(aw_idt_push);

    always_comb begin
        for (int i = 0; i < AW_IDT_N; i++) begin
            aw_idt_cnt_nx[i] = aw_idt_cnt[i]
                + (AW_TRK_AW+1)'(aw_idt_push && (aw_idt_widx == 1'(i)))
                - (AW_TRK_AW+1)'(aw_idt_pop  && (aw_idt_ridx == 1'(i)));
        end
        aw_out_cnt_nx = aw_out_cnt + (AW_TRK_AW+1)'(aw_idt_push)
                          - (AW_TRK_AW+1)'(aw_idt_pop);
    end

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i] <= '0;
                aw_idt_tgt[i] <= '0;
            end
            aw_idt_busy <= '0;
            aw_out_cnt <= '0;
            aw_trk_full <= 1'b0;
        end else begin
            if (aw_idt_push) aw_idt_tgt[aw_idt_widx] <= comb_slave_select_aw;
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i]  <= aw_idt_cnt_nx[i];
                aw_idt_busy[i] <= (aw_idt_push && (aw_idt_widx == 1'(i)))
                                    || (aw_idt_cnt[i] > (AW_TRK_AW+1)'(1))
                                    || ((aw_idt_cnt[i] == (AW_TRK_AW+1)'(1)) &&
                                        !(aw_idt_pop && (aw_idt_ridx == 1'(i))));
            end
            aw_out_cnt  <= aw_out_cnt_nx;
            aw_trk_full <=
                ((aw_out_cnt == (AW_TRK_AW+1)'(AW_TRK_DEPTH))   && (aw_inc_n == 2'(aw_idt_pop))) ||
                ((aw_out_cnt == (AW_TRK_AW+1)'(AW_TRK_DEPTH-1)) && (aw_inc_n == 2'(aw_idt_pop) + 2'd1));
        end
    )

    // bridge BUG-009 (was BRIDGE-011): a bounded number in flight, so no
    // count wraps; AW_TRK_DEPTH is the port's outstanding limit.
    // Target match is a one-hot AND: the stored target and the decode
    // are both one-hot (no hit selects the catch-all).
    logic aw_id_ok;
    assign aw_id_ok    = !aw_idt_busy[aw_idt_widx] ||
                           ((|(aw_idt_tgt[aw_idt_widx] & comb_slave_select_aw)));

    // One width path: every response arrives on it; the crossbar has
    // already chosen among the slaves behind it.
    assign b_slave_select = 22'b0000000000000000000001;

    // -------- AW->W slave_select tracking FIFO --------
    // Same push as AW (records slave_select at handshake);
    // pops on wlast so W#2's path-active gating doesn't wait
    // for B#1 to return. Without this, back-to-back writes
    // to different-width slaves stamp W#2's data on AW#1's
    // bucket (see multi-master 128b->32b/128b regression).
    logic [NUM_SLAVES-1:0] w_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] w_trk_wptr, w_trk_rptr;
    logic w_trk_push, w_trk_pop;

    assign w_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign w_trk_pop  = fub_axi_wvalid && fub_axi_wready && fub_axi_wlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            w_trk_wptr <= '0;
            w_trk_rptr <= '0;
        end else begin
            if (w_trk_push) begin
                w_trk_mem[w_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                w_trk_wptr <= w_trk_wptr + 1'b1;
            end
            if (w_trk_pop) begin
                w_trk_rptr <= w_trk_rptr + 1'b1;
            end
        end
    )

    assign w_slave_select = (w_trk_wptr != w_trk_rptr)
                          ? w_trk_mem[w_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // A new AW may target a different slave only once every W burst
    // already accepted has gone: W carries no ID and follows AW order,
    // so two masters each with W owed to two slaves could otherwise
    // wait on each other at the slaves' W ports (crossed W deadlock).
    assign aw_gate_ok = aw_id_ok && !aw_trk_full &&
                        ((w_trk_wptr == w_trk_rptr) ||
                         (|(w_slave_select & comb_slave_select_aw)));

    // OUTPUT slave_select_ar mirrors the live combinational decode.
    assign slave_select_ar = comb_slave_select_ar;

    localparam int AR_TRK_DEPTH = 16;
    localparam int AR_TRK_AW    = 4;
    // -------- AR per-ID target table (fixes bridge GitHub #119 L1) --------
    // 2 entries indexed by the ID's low 1 bit(s). An ID with requests
    // in flight may only add more to the SAME slave (AXI same-ID order);
    // any other ID may go to any slave. IDs that share the index bits are
    // treated as one ID: safe, at worst a needless stall.
    localparam int AR_IDT_N = 2;
    logic [AR_TRK_AW:0]   ar_idt_cnt [AR_IDT_N];
    logic [NUM_SLAVES-1:0] ar_idt_tgt [AR_IDT_N];
    logic [AR_TRK_AW:0]   ar_out_cnt;
    // Next counts, and registered flags taken from them, so the gate a
    // request sees is a 1-bit lookup and a one-hot AND, not a counter
    // mux and compare in series with the crossbar's arbitration.
    logic [AR_TRK_AW:0]   ar_idt_cnt_nx [AR_IDT_N];
    logic [AR_TRK_AW:0]   ar_out_cnt_nx;
    logic [AR_IDT_N-1:0] ar_idt_busy;
    logic                  ar_trk_full;
    logic [0:0] ar_idt_widx, ar_idt_ridx;
    logic ar_idt_push, ar_idt_pop;
    assign ar_idt_widx = fub_axi_arid[0:0];
    assign ar_idt_ridx = fub_axi_rid[0:0];
    assign ar_idt_push = fub_axi_arvalid && fub_axi_arready;
    assign ar_idt_pop  = fub_axi_rvalid && fub_axi_rready && fub_axi_rlast;
    logic [1:0] ar_inc_n;   // pushes this cycle
    assign ar_inc_n = 2'(ar_idt_push);

    always_comb begin
        for (int i = 0; i < AR_IDT_N; i++) begin
            ar_idt_cnt_nx[i] = ar_idt_cnt[i]
                + (AR_TRK_AW+1)'(ar_idt_push && (ar_idt_widx == 1'(i)))
                - (AR_TRK_AW+1)'(ar_idt_pop  && (ar_idt_ridx == 1'(i)));
        end
        ar_out_cnt_nx = ar_out_cnt + (AR_TRK_AW+1)'(ar_idt_push)
                          - (AR_TRK_AW+1)'(ar_idt_pop);
    end

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AR_IDT_N; i++) begin
                ar_idt_cnt[i] <= '0;
                ar_idt_tgt[i] <= '0;
            end
            ar_idt_busy <= '0;
            ar_out_cnt <= '0;
            ar_trk_full <= 1'b0;
        end else begin
            if (ar_idt_push) ar_idt_tgt[ar_idt_widx] <= comb_slave_select_ar;
            for (int i = 0; i < AR_IDT_N; i++) begin
                ar_idt_cnt[i]  <= ar_idt_cnt_nx[i];
                ar_idt_busy[i] <= (ar_idt_push && (ar_idt_widx == 1'(i)))
                                    || (ar_idt_cnt[i] > (AR_TRK_AW+1)'(1))
                                    || ((ar_idt_cnt[i] == (AR_TRK_AW+1)'(1)) &&
                                        !(ar_idt_pop && (ar_idt_ridx == 1'(i))));
            end
            ar_out_cnt  <= ar_out_cnt_nx;
            ar_trk_full <=
                ((ar_out_cnt == (AR_TRK_AW+1)'(AR_TRK_DEPTH))   && (ar_inc_n == 2'(ar_idt_pop))) ||
                ((ar_out_cnt == (AR_TRK_AW+1)'(AR_TRK_DEPTH-1)) && (ar_inc_n == 2'(ar_idt_pop) + 2'd1));
        end
    )

    // bridge BUG-009 (was BRIDGE-011): a bounded number in flight, so no
    // count wraps; AR_TRK_DEPTH is the port's outstanding limit.
    // Target match is a one-hot AND: the stored target and the decode
    // are both one-hot (no hit selects the catch-all).
    logic ar_id_ok;
    assign ar_id_ok    = !ar_idt_busy[ar_idt_widx] ||
                           ((|(ar_idt_tgt[ar_idt_widx] & comb_slave_select_ar)));
    assign ar_gate_ok = ar_id_ok && !ar_trk_full;

    // One width path: every response arrives on it; the crossbar has
    // already chosen among the slaves behind it.
    assign r_slave_select = 22'b0000000000000000000001;

    // AW-ready MUX (combinational comb_slave_select_aw — awaddr is live during awvalid)
    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            22'b0000000000000000000001: begin  // Slave 0 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000000000010: begin  // Slave 1 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000000000100: begin  // Slave 2 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000000001000: begin  // Slave 3 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000000010000: begin  // Slave 4 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000000100000: begin  // Slave 5 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000001000000: begin  // Slave 6 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000010000000: begin  // Slave 7 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000000100000000: begin  // Slave 8 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000001000000000: begin  // Slave 9 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000010000000000: begin  // Slave 10 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000000100000000000: begin  // Slave 11 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000001000000000000: begin  // Slave 12 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000010000000000000: begin  // Slave 13 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000000100000000000000: begin  // Slave 14 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000001000000000000000: begin  // Slave 15 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000010000000000000000: begin  // Slave 16 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0000100000000000000000: begin  // Slave 17 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0001000000000000000000: begin  // Slave 18 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0010000000000000000000: begin  // Slave 19 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b0100000000000000000000: begin  // Slave 20 (32b)
                fub_axi_awready = host_32b_awready;
            end
            22'b1000000000000000000000: begin  // Slave 21 (32b)
                fub_axi_awready = host_32b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Hold off a new AW the gate refuses (see aw_gate_ok).
        if (!aw_gate_ok) fub_axi_awready = 1'b0;
    end

    // W-ready MUX (FIFO-tracked w_slave_select — awaddr has already reverted by W phase)
    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            22'b0000000000000000000001: begin  // Slave 0 (32b)
                fub_axi_wready = host_32b_wready;
            end
            22'b0000000000000000000010: begin  // Slave 1 (32b)
                fub_axi_wready = host_32b_wready;
            end
            22'b0000000000000000000100: begin  // Slave 2 (32b)
                fub_axi_wready = host_32b_wready;
            end
            22'b0000000000000000001000: begin  // Slave 3 (32b)
                fub_axi_wready = host_32b_wready;
            end
            22'b0000000000000000010000: begin  // Slave 4 (32b)
                fub_axi_wready = host_32b_wready;
            end
            22'b0000000000000000100000: begin  // Slave 5 (32b)
                fub_axi_wready = host_32b_wready;
            end
            22'b0000000000000001000000: begin  // Slave 6 (32b)
                fub_axi_wready = host_32b_wready;
            end
